def main():
    if getattr(sys, 'frozen', False) and (Path(sys.executable).parent / 'TEST-ONLY.txt').exists():
        os.environ.setdefault('HUB_PORT', '18081')
        os.environ.setdefault('AGENTHUB_FILE_PORT', '18092')
        os.environ.setdefault('AGENTHUB_STATE_DIR', str(Path(os.environ.get('LOCALAPPDATA', str(Path.home()))) / 'AgentHub-Test' / 'state'))
        os.environ.setdefault('AGENTHUB_WORK_ROOT', str(Path(os.environ.get('LOCALAPPDATA', str(Path.home()))) / 'AgentHub-Test' / 'work'))
    if sys.argv[1:] == ['--file-browser']:
        runpy.run_path(str(Path(getattr(sys, '_MEIPASS', Path(__file__).resolve().parent.parent)) / 'file-browser' / 'app.py'), run_name='__main__')
        return
    if getattr(sys, 'frozen', False) and '--serve' not in sys.argv:
        from hub.runtime import STATE
        STATE.mkdir(parents=True, exist_ok=True)
        url = 'http://127.0.0.1:' + os.environ.get('HUB_PORT', '8081')
        try:
            with urllib.request.urlopen(url + '/api/onboarding', timeout=2) as response:
                if response.status == 200:
                    webbrowser.open(url)
                    return
        except Exception:
            pass
        with (STATE / 'launcher.log').open('a', encoding='utf-8') as log:
            while True:
                child = subprocess.Popen([sys.executable, '--serve'], stdout=log, stderr=log,
                                         creationflags=0x08000000)
                if not os.environ.get('AGENTHUB_NO_BROWSER'):
                    for _ in range(100):
                        if child.poll() is not None:
                            break
                        try:
                            with urllib.request.urlopen(url + '/api/onboarding', timeout=.4):
                                webbrowser.open(url)
                                break
                        except Exception:
                            time.sleep(.2)
                if child.wait() != 42:
                    return
    if not getattr(sys, "frozen", False):
        sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
    from app import main as serve
    serve()

